// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 amount, address recipient) public {
        vm.assume(recipient != address(c) && recipient != address(this) && recipient != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balBeforeRecipient = recipient.balance;
        uint256 balBeforeC = address(c).balance;
        c.withdrawAll(recipient);
        uint256 balAfterRecipient = recipient.balance;
        uint256 balAfterC = address(c).balance;
        assertTrue(balAfterRecipient == balBeforeRecipient + balBeforeC && balAfterC == 0);
    }
}
